std::string_view LevelToString(Level level) noexcept {
    switch (level) {
        case Level::Debug: return "DEBUG";
        case Level::Info: return "INFO";
        case Level::Warn: return "WARN";
        case Level::Error: return "ERROR";
        case Level::Fatal: return "FATAL";
        default: assert(false); return "UNKNOWN";
    }
}

std::string to_string(Level level) noexcept {
    return std::string {LevelToString(level)};
}

std::ostream& operator<<(std::ostream& os, Level level) noexcept {
    return os << LevelToString(level);
}

Level StringToLevel(std::string str) {
    if (str == "DEBUG") return Level::Debug;
    else if (str == "INFO") return Level::Info;
    else if (str == "WARN") return Level::Warn;
    else if (str == "ERROR") return Level::Error;
    else if (str == "FATAL") return Level::Fatal;
    throw std::invalid_argument {"Invalid log level: " + str};
}

std::string_view AppenderTypeToString(AppenderType type) noexcept {
    switch (type) {
        case AppenderType::StdOut: return "stdout";
        case AppenderType::File: return "file";
        default: assert(false); return "UNKNOWN";
    }
}

std::string to_string(AppenderType type) noexcept {
    return std::string {AppenderTypeToString(type)};
}

std::ostream& operator<<(std::ostream& os, AppenderType type) noexcept {
    return os << AppenderTypeToString(type);
}

AppenderType StringToAppenderType(std::string str) {
    if (str == "stdout") return AppenderType::StdOut;
    else if (str == "file") return AppenderType::File;
    throw std::invalid_argument {"Invalid appender type: " + str};
}

