Logger::Logger(std::string_view name, log::Level level, std::optional<std::size_t> capacity) noexcept
    : name_ {name},
      level_ {level} {
    if (capacity && *capacity > 0) {
        async_ = true;
        event_deque_ = std::make_unique<BlockDeque<Event::Ptr>>(*capacity);
        writer_thread_ = std::make_unique<std::thread>(&Logger::AsyncLogProc, this);
    }
}

Logger::~Logger() noexcept {
    if (async_) {
        event_deque_->Close();
        writer_thread_->join();
    }
}

void Logger::Log(Event::Ptr event) noexcept {
    if (event->Level() < level_) return;
    if (async_) {
        event_deque_->Push(event);
    } else {
        SyncLog(*event);
    }
}

void Logger::AddAppender(Appender::Ptr appender) noexcept {
    std::lock_guard lock {mtx_};
    appenders_.push_back(appender);
}

void Logger::RemoveAppender(Appender::Ptr appender) noexcept {
    std::lock_guard lock {mtx_};
    appenders_.remove_if([appender](const auto& a) { return a == appender; });
}

void Logger::ClearAppenders() noexcept {
    std::lock_guard lock {mtx_};
    appenders_.clear();
}

log::Level Logger::GetLevel() const noexcept {
    return level_;
}

void Logger::SetLevel(log::Level level) noexcept {
    std::lock_guard lock {mtx_};
    level_ = level;
}

Formatter::Ptr Logger::GetDefaultFormatter() const noexcept {
    std::lock_guard lock {mtx_};
    return formatter_;
}

void Logger::SetDefaultFormatter(Formatter::Ptr formatter) noexcept {
    std::lock_guard lock {mtx_};
    formatter_ = formatter;
}

void Logger::SetDefaultFormatter(std::string_view pattern) {
    auto new_formatter = std::make_shared<Formatter>(pattern);
    SetDefaultFormatter(new_formatter);
}

std::string_view Logger::Name() const noexcept {
    return name_;
}

std::size_t Logger::Capacity() const noexcept {
    return capacity_;
}

void Logger::AsyncLogProc() noexcept {
    while (true) {
        auto event = event_deque_->Pop();
        if (!event) break;
        SyncLog(*event);
    }
}

void Logger::SyncLog(const Event& event) noexcept {
    std::lock_guard lock {mtx_};
    for (const auto& appender : appenders_) {
        appender->Log(*this, event);
    }
}

std::string Logger::ToYamlString() const noexcept {
    std::ostringstream oss;
    oss << "{ name: \"" << name_ << "\", level: \"" << to_string(level_) << "\"";
    if (capacity_) {
        oss << ", capacity: " << *capacity_;
    }
    if (formatter_->Pattern() != Formatter::Default()->Pattern()) {
        oss << ", formatter: \"" << formatter_->Pattern() << "\"";
    }
    if (!appenders_.empty()) {
        oss << ", appenders: [";
        for (const auto& appender : appenders_) {
            oss << appender->ToYamlString() << ", ";
        }
        oss.seekp(-2, std::ios_base::end);
        oss << " ]";
    }
    oss << " }";
    return oss.str();
}

void Log(Logger::Ptr logger, Event::Ptr event) noexcept {
    logger->Log(event);
}

