}

Logger::Ptr Manager::FindLogger(std::string_view name, log::Level level, std::optional<std::size_t> capacity) noexcept {
    std::lock_guard lock {mtx_};
    auto it = loggers_.find(name);
    if (it != loggers_.end()) return it->second;
    auto logger = std::make_shared<Logger>(name, level, capacity);
    loggers_[std::string {name}] = logger;
    return logger;
}

void Manager::RemoveLogger(std::string_view name) noexcept {
    std::lock_guard lock {mtx_};
    loggers_.erase(name);
}

std::string Manager::ToYamlString() const noexcept {
    std::ostringstream oss;
    oss << "{ name: \"" << name_ << "\", loggers: [";
    for (const auto& [name, logger] : loggers_) {
        oss << logger->ToYamlString() << ", ";
    }
    oss.seekp(-2, std::ios_base::end);
    oss << " ] }";
    return oss.str();
}

Manager::Ptr RootManager() noexcept {
    static auto root_manager = std::make_shared<Manager>("root");
    return root_manager;
}

Logger::Ptr RootLogger() noexcept {
    return RootManager()->FindLogger("root");
}

Logger::Ptr FindLogger(std::string_view name) noexcept {
    return RootManager()->FindLogger(name);
}

